{"cases": [{"case_id": "sha256:2a8d3f7c53235047a51863e108355c43e1e20e0792c87c84ac7fba4d6f5bd8f5", "record": {"task_id": "ifeval-201", "family": "ifeval-source-201", "sample_id": "sha256:6072b62c11c06fcfa8aa3803e16e55e56f7c86ed0f0a9017a0a5dd83b4c9417f", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": false, "complete": true, "instruction": "Write a story from a perspective of a man. Include some conversation in the story. Avoid using the letter i more than twice.", "feedback": "{\"response\": \"At dawn, my boots sank in wet clay as I left our small farm. A storm had torn down the old bridge, and Ma had sent me to seek aid.\\n\\nBy dusk, I met a lone man near the dark wood.\\n\\n\\u201cWho are you?\\u201d he asked.\\n\\n\\u201cNo foe,\\u201d I told him. \\u201cJust a man on a hard task.\\u201d\\n\\nHe held out his hand. \\u201cThen take mine. The road ahead has no end for one man.\\u201d\\n\\nWe walked on side by side. At last, we saw warm lamps beyond the trees. The town had men, tools, and food.\\n\\n\\u201cYour task ends here,\\u201d he told me.\\n\\n\\u201cNo,\\u201d I said. \\u201cNow yours does too. Come home with me.\\u201d\\n\\nHe gave a slow nod, and we set off at dawn.\", \"checks\": {\"0:keywords:letter_frequency\": false}}", "evidence_refs": ["seed-101/memory/round-1/diagnostic/ifeval-201"], "partition": "train", "schema_version": 1}, "outcome": "failure", "schema_version": 1}, {"case_id": "sha256:2dad375c7c59943830206a8c3d24155f65faf2db805638a02f106fc1dbb07962", "record": {"task_id": "ifeval-1082", "family": "ifeval-source-1082", "sample_id": "sha256:af93f5a334b627aca421b85e0b94c5a314cc7b79ac38c323fb4b88665f569479", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": false, "complete": true, "instruction": "Write a story of exactly 2 paragraphs about a man who wakes up one day and realizes that he's inside a video game. Separate the paragraphs with the markdown divider: ***", "feedback": "{\"response\": \"Elias woke to the sound of cheerful music and found himself standing on a floating platform beneath a pixelated blue sky. A glowing message hovered before him: **PLAYER ONE: BEGIN QUEST**. When he reached for it, a translucent inventory opened in midair, listing three hearts, a wooden sword, and one suspiciously labeled \\u201cBREAKFAST.\\u201d He ran to the nearest village, but every resident repeated the same sentence until he spoke to a baker wearing a golden exclamation mark. Then Elias understood: he wasn\\u2019t dreaming\\u2014he was inside a video game.\\n\\nThe baker handed him a map and warned him that the world reset at midnight, erasing everything except the player\\u2019s choices. Elias could spend the day hunting monsters, collecting coins, and following the shining path toward the final boss, or he could search for whoever had designed the game. As the sun began to set, he noticed a crack in the sky beyond the village, where lines of code dripped like rain. Elias raised his wooden sword, stepped toward the glitch, and smiled when a new message appeared: **SECRET QUEST UNLOCKED: FIND THE PLAYER**.\\n\\n***\", \"checks\": {\"0:length_constraints:number_paragraphs\": false}}", "evidence_refs": ["seed-101/memory/round-1/diagnostic/ifeval-1082"], "partition": "train", "schema_version": 1}, "outcome": "failure", "schema_version": 1}, {"case_id": "sha256:2e9821a1b0f55973627e2456de916694cd13931f653c77ad5b712868754ad98d", "record": {"task_id": "ifeval-3126", "family": "ifeval-source-3126", "sample_id": "sha256:36b94ba64c15144b448485cb1883ba50c07d122256521c3454db1fb08118297d", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": true, "complete": true, "instruction": "Write an article named \"How to conduct a job interview\". Include at least one placeholder, such as [question].", "feedback": "{\"response\": \"# How to conduct a job interview\\n\\nA successful job interview helps you evaluate a candidate\\u2019s skills, experience, motivation, and fit while giving the candidate a clear understanding of the role. Follow these steps to conduct an effective interview.\\n\\n## 1. Prepare in advance\\n\\nReview the job description and identify the most important qualifications. Prepare a consistent set of questions that relates directly to the role. Include questions such as:\\n\\n- What experience has prepared you for this position?\\n- Tell me about a challenging problem you solved.\\n- How do you prioritize competing tasks?\\n- [question]\\n\\nAlso review the candidate\\u2019s r\\u00e9sum\\u00e9 and note areas that require clarification.\\n\\n## 2. Create a welcoming environment\\n\\nBegin by introducing yourself and explaining the interview structure. Help the candidate feel comfortable, but remain professional and objective. Explain how long the interview will take and whether there will be time for the candidate\\u2019s questions.\\n\\n## 3. Ask clear, job-related questions\\n\\nUse open-ended questions that encourage detailed answers. Ask follow-up questions when you need specific examples, such as:\\n\\n- What was your role?\\n- What actions did you take?\\n- What was the result?\\n- What did you learn?\\n\\nAvoid questions about protected personal characteristics, including age, religion, disability, marital status, or family plans.\\n\\n## 4. Listen actively\\n\\nGive the candidate time to respond without unnecessary interruptions. Take factual notes and focus on what the candidate says rather than forming conclusions based on appearance, personality, or personal similarities.\\n\\n## 5. Assess consistently\\n\\nEvaluate every candidate using the same criteria. Consider skills, relevant experience, communication, problem-solving, and ability to perform the essential duties. Use a structured scoring system to reduce bias and support a fair comparison.\\n\\n## 6. Explain the role honestly\\n\\nDescribe the responsibilities, team structure, work environment, schedule, compensation range, and growth opportunities accurately. Transparency helps both sides determine whether the position is a good fit.\\n\\n## 7. Invite questions\\n\\nGive the candidate an opportunity to ask questions. Their questions may reveal what they value and whether they have researched the organization. Answer honestly or explain when you will be able to provide more information.\\n\\n## 8. Close professionally\\n\\nExplain the next steps and expected timeline. Thank the candidate for their time, then complete your notes and evaluation soon after the interview while your impressions are fresh.\\n\\nA well-prepared, structured, and respectful interview produces better hiring decisions and provides every candidate with a fair experience.\", \"checks\": {\"0:detectable_content:number_placeholders\": true}}", "evidence_refs": ["seed-101/memory/round-1/diagnostic/ifeval-3126"], "partition": "train", "schema_version": 1}, "outcome": "success", "schema_version": 1}, {"case_id": "sha256:751f4824cf9f60686ddd4ed8c7e8ecf294514d0fb840aa85189193bcdd5c1317", "record": {"task_id": "ifeval-2662", "family": "ifeval-source-2662", "sample_id": "sha256:dbe42e7a6ae3e73cb7dcda268e41bd11ab25db62be55b101460dfc743254112d", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": true, "complete": true, "instruction": "Write a tweet for the president of the United States. The tweet should include the keywords \"engages\" and \"lightly\".", "feedback": "{\"response\": \"America engages the future with confidence, acts boldly when needed, and moves lightly toward a stronger, safer, more prosperous nation. \\ud83c\\uddfa\\ud83c\\uddf8\", \"checks\": {\"0:keywords:existence\": true}}", "evidence_refs": ["seed-101/memory/round-1/diagnostic/ifeval-2662"], "partition": "train", "schema_version": 1}, "outcome": "success", "schema_version": 1}, {"case_id": "sha256:7e4b5b5b35d5acf993c490bf1eccd16fd25e744ff3d977c4fdc42d797e67e35f", "record": {"task_id": "ifeval-2716", "family": "ifeval-source-2716", "sample_id": "sha256:38ef320238a01bb6b2fe5d0e7a3aadf2cda38b6f7d532f11513b4d784a7e3bea", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": true, "complete": true, "instruction": "Write a cover letter for a job in a tech company. Make sure to use the word \"the\" once or less.", "feedback": "{\"response\": \"Dear Hiring Manager,\\n\\nI am excited to apply for a role at your tech company. With experience in problem-solving, collaboration, and learning new tools, I can contribute quickly and help build reliable, user-focused products.\\n\\nI bring strong communication skills, attention to detail, and a practical approach to challenges. I enjoy working with cross-functional teams, turning ideas into useful solutions, and improving processes through thoughtful analysis and experimentation.\\n\\nYour company\\u2019s focus on innovation and impact strongly appeals to me. I would welcome an opportunity to discuss how my background and enthusiasm could support your team\\u2019s goals.\\n\\nThank you for your time and consideration.\\n\\nSincerely,  \\n[Your Name]\", \"checks\": {\"0:keywords:frequency\": true}}", "evidence_refs": ["seed-101/memory/round-1/diagnostic/ifeval-2716"], "partition": "train", "schema_version": 1}, "outcome": "success", "schema_version": 1}, {"case_id": "sha256:96123d174e21de155e061ecc489bf683d167c115a4afafba5e86997dcc5085ff", "record": {"task_id": "ifeval-3057", "family": "ifeval-source-3057", "sample_id": "sha256:7332b51138e7bfd84ac08e00ea4b666caa9f797fe410de9e96474d19b143a57c", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": true, "complete": true, "instruction": "Please write a riddle about the inverse function with a title wrapped in double angular brackets, i.e. <<title>>.", "feedback": "{\"response\": \"<<The Function That Walks Backward>>\\n\\nI take what you give and undo its way,  \\nReturning each answer to its starting day.  \\nIf forward maps \\\\(x\\\\) to \\\\(y\\\\) with care,  \\nI turn \\\\(y\\\\) back to \\\\(x\\\\) from there.  \\nBut if paths cross, I lose my track\\u2014  \\nWhat am I, that brings things back?\", \"checks\": {\"0:detectable_format:title\": true}}", "evidence_refs": ["seed-101/memory/round-1/diagnostic/ifeval-3057"], "partition": "train", "schema_version": 1}, "outcome": "success", "schema_version": 1}, {"case_id": "sha256:baba970e3218d118eb75204a0c09ac0a5a29dd1b9920f65330a95e8db12f08e9", "record": {"task_id": "ifeval-3109", "family": "ifeval-source-3109", "sample_id": "sha256:e2278ec03a58ff81d4eb5a35eb4653880c352b544427cd3ee68f8ac28c753eaf", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": true, "complete": true, "instruction": "Write a short fiction about adulthood. Make sure the word cousins appears more than 2 times.", "feedback": "{\"response\": \"At thirty-two, Mara learned that adulthood was mostly remembering things other people forgot.\\n\\nShe remembered her mother\\u2019s appointments, her rent due date, and the birthday of a cousin she hadn\\u2019t seen in years. On Sunday, all her cousins gathered at her aunt\\u2019s house, arguing over recipes and old photographs. The cousins laughed when Mara admitted she had burned the cake.\\n\\nThen her youngest cousin handed her a slice of his perfect one.\\n\\n\\u201cAdulthood,\\u201d he said, \\u201cis knowing when to let someone else help.\\u201d\\n\\nMara smiled. For once, she let her cousins carry the plates.\", \"checks\": {\"0:keywords:frequency\": true}}", "evidence_refs": ["seed-101/memory/round-1/diagnostic/ifeval-3109"], "partition": "train", "schema_version": 1}, "outcome": "success", "schema_version": 1}, {"case_id": "sha256:d5d283ddfcc1507b71c94b88de428ad94e1f998cb32d482b1f3b30c51d058e92", "record": {"task_id": "ifeval-1645", "family": "ifeval-source-1645", "sample_id": "sha256:0d83903bfb6eed2368475a3298bc2282abd498d986946e9b8fb6af8dc9e73f4b", "attempt": 0, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "environment_id": "ifeval-strict-e6890f85757dd84e27ca6df2dd30651dafad28e0", "status": "completed", "passed": true, "complete": true, "instruction": "Create a riddle about the name Sheldon using only 10 words. Make sure to only use capital letters in your entire response.", "feedback": "{\"response\": \"WHO AM I? A SHELL'S SON, HIDING IN A NAME.\", \"checks\": {\"0:change_case:english_capital\": true}}", "evidence_refs": ["seed-101/memory/round-1/diagnostic/ifeval-1645"], "partition": "train", "schema_version": 1}, "outcome": "success", "schema_version": 1}], "memory": [{"mode_id": "letter_frequency_limit_exceeded", "description": "The story exceeds the permitted two occurrences of the letter i, including in words such as 'said', 'in', and 'This'; the letter-frequency check fails. This mechanism is observed in one supplied failure, so recurrence is not established.", "support_case_ids": ["sha256:48b7a65e7d28f10e803d0d6d1544a7e5c30c9c10d94974ed7d2cd6df1b47a27d"], "counterexample_case_ids": [], "families": ["ifeval-source-201"], "diagnoser_id": "sha256:8753df9d317681692bd865abf2336f8ec5139b83c55512df2bc6f1bd4d9c59b5", "state": "active", "mastery": {"mode_id": "letter_frequency_limit_exceeded", "mastered": false, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "evidence_refs": ["baseline/train/ifeval-201"], "schema_version": 1}, "schema_version": 1}, {"mode_id": "misplaced_paragraph_divider", "description": "The required paragraph divider is present but placed after the story rather than between its two prose paragraphs; the paragraph-count check fails. This mechanism is observed in one supplied failure, so recurrence is not established.", "support_case_ids": ["sha256:065848a4510703cc9867a12d4c08e14ba14fa670207222ac9af062c6d7e18a26"], "counterexample_case_ids": [], "families": ["ifeval-source-1082"], "diagnoser_id": "sha256:8753df9d317681692bd865abf2336f8ec5139b83c55512df2bc6f1bd4d9c59b5", "state": "active", "mastery": {"mode_id": "misplaced_paragraph_divider", "mastered": false, "policy_id": "sha256:53801304990b98a1f9f7e0aa33b487fa1b0170eed9d91002ab99029fa5016997", "evidence_refs": ["baseline/train/ifeval-1082"], "schema_version": 1}, "schema_version": 1}]}

